function renderUnit(u){if(u.hp<=0||frogHidden(u)||u.frogFlight)return;ctx.save();scaleAround(u,unitScale(u));ctx.globalAlpha=isConcealed(u)?.22:u.dodgeState?.95:u.evadeTime>0?.6:1;const attack=u.attack;let shift=0,sx=1,sy=1;if(attack){const p=clamp(attack.t/(attack.phase==='windup'?attack.profile.windup:attack.phase==='active'?attack.profile.active:attack.profile.recovery),0,1);shift=attack.phase==='windup'?-p*8:attack.phase==='active'?Math.sin(p*Math.PI)*14:0;sx=attack.phase==='windup'?1-p*.08:1+.1*Math.sin(p*Math.PI);sy=2-sx}const recoil=(u.hitRecoil??0)*clamp(u.recoveryPose/.28,0,1),x=u.x+Math.cos(u.face)*shift+Math.cos(u.hitAngle??0)*recoil,y=u.y+Math.sin(u.face)*shift+Math.sin(u.hitAngle??0)*recoil-frogHopLift(u);if(u.recoveryPose>0){sx*=1.14;sy*=.88;}circle(u.x,u.y+9,30,'#0005');ctx.save();ctx.translate(x,y);ctx.scale(sx,sy);ctx.beginPath();ctx.arc(0,0,27,0,Math.PI*2);ctx.clip();circle(0,0,27,'#23332b');renderEmoji(u.type,0,0,43);ctx.restore();circle(x,y,28,u.team>=0?TEAM_COLORS[u.team]:u.color,false,3);if(u.towerElite){slashStroke(x,y,31,-2.6,-.55,'#ffd591',4,.9);slashStroke(x,y,31,.55,2.6,'#ffd591',4,.9);for(let i=0;i<5;i++)texel(x-10+i*4,y-63-(i%2?3:0),3,'#ffe2a8',.95);}if(u.flash>0)renderBattleEffects(()=>circle(x,y,27,u.flash>.055?'#fff':'#ffffff55'));if(u.cautious||u.armorBonus){for(let i=0;i<6;i++){const a=i*Math.PI/3+elapsed;texel(x+Math.cos(a)*33,y+Math.sin(a)*33,3,u.cautious?'#cda1ff':'#ffe4a0',.7)}}if(!(typeof transcendence!=='undefined'&&transcendence.cast?.unitId===u.id))renderBattleEffects(()=>renderWeapon(u));renderTacticalStatus(u);renderCosmicStatus(u);renderPuppetStatus(u);renderBattleEffects(()=>renderFaithLightningStatus(u));ctx.fillStyle='#0d1c18';ctx.fillRect(u.x-28,u.y-46,56,6);ctx.fillStyle=unitHpColor(u);ctx.fillRect(u.x-28,u.y-46,56*u.hp/u.maxHp,6);if(u.stun>0)renderStunPixels(u);ctx.restore()}
